) AS t(county_key, county_name, boundary)
) b
LEFT JOIN (
  SELECT * FROM (
SELECT * FROM default.nphiis_vhf_line_list
  ) base_rows
  WHERE 1 = 1
{%- for f in get_filters('Disease', remove_filter=True) %}
{%- if f.op == 'IN' %}
  AND base_rows.`Disease` IN {{ f.val | where_in }}
{%- elif f.op == 'NOT IN' %}
  AND base_rows.`Disease` NOT IN {{ f.val | where_in }}
{%- elif f.op == '==' %}
  AND base_rows.`Disease` IN {{ [f.val] | where_in }}
{%- elif f.op == '!=' %}
  AND base_rows.`Disease` NOT IN {{ [f.val] | where_in }}
{%- endif %}
{%- endfor %}
{%- for f in get_filters('Classification', remove_filter=True) %}
{%- if f.op == 'IN' %}
  AND base_rows.`Classification` IN {{ f.val | where_in }}
{%- elif f.op == 'NOT IN' %}
  AND base_rows.`Classification` NOT IN {{ f.val | where_in }}
{%- elif f.op == '==' %}
  AND base_rows.`Classification` IN {{ [f.val] | where_in }}
{%- elif f.op == '!=' %}
  AND base_rows.`Classification` NOT IN {{ [f.val] | where_in }}
{%- endif %}
{%- endfor %}
{%- for f in get_filters('County', remove_filter=True) %}
{%- if f.op == 'IN' %}
  AND base_rows.`County` IN {{ f.val | where_in }}
{%- elif f.op == 'NOT IN' %}
  AND base_rows.`County` NOT IN {{ f.val | where_in }}
{%- elif f.op == '==' %}
  AND base_rows.`County` IN {{ [f.val] | where_in }}
{%- elif f.op == '!=' %}
  AND base_rows.`County` NOT IN {{ [f.val] | where_in }}
{%- endif %}
{%- endfor %}
{%- for f in get_filters('Sub County', remove_filter=True) %}
{%- if f.op == 'IN' %}
  AND base_rows.`Sub County` IN {{ f.val | where_in }}
{%- elif f.op == 'NOT IN' %}
  AND base_rows.`Sub County` NOT IN {{ f.val | where_in }}
{%- elif f.op == '==' %}
  AND base_rows.`Sub County` IN {{ [f.val] | where_in }}
{%- elif f.op == '!=' %}
  AND base_rows.`Sub County` NOT IN {{ [f.val] | where_in }}
{%- endif %}
{%- endfor %}
{%- set time_filter = get_time_filter('Date Reported', strftime='%Y-%m-%d', remove_filter=True) %}
{%- if time_filter.from_expr %}
  AND base_rows.`Date Reported` >= CAST('{{ time_filter.from_expr }}' AS DATE)
{%- endif %}
{%- if time_filter.to_expr %}
  AND base_rows.`Date Reported` < CAST('{{ time_filter.to_expr }}' AS DATE)
{%- endif %}
) v ON REGEXP_REPLACE(UPPER(v.`County`), '[^A-Z]', '') = b.county_key
